'use client';

import { useCallback, useEffect, useMemo, useState, type ComponentProps } from 'react';
import NumberFlow from '@number-flow/react';
import {
	Area,
	AreaChart,
	CartesianGrid,
	ReferenceDot,
	ReferenceLine,
	XAxis,
	YAxis
} from 'recharts';
import { ForecastIcon, type IconSet } from './forecast-icons';
import type {
	ForecastType,
	LocationInput,
	TidePoint,
	TidePrediction,
	TideReading,
	TideUnit
} from '@/lib/wxcn/types.js';
import { sampleTideSeries, sampleTideTime, sampleTides } from '@/lib/wxcn/tides.js';
import { tideState, tideTimestamp } from '@/lib/wxcn/tide-state.js';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';

export type TideForecastProps = {
	iconType?: IconSet;
	timeZone?: string;
	type?: ForecastType;
	size?: 'sm' | 'default' | 'lg';
	density?: 'compact' | 'comfortable';
	className?: string;
	unit?: TideUnit;
	location?: LocationInput;
	predictions?: TidePrediction[];
	example?: boolean;
	series?: TidePoint[];
	reading?: TideReading | null;
	at?: number;
	sourceLabel?: string;
};

const defaultLocation: LocationInput = {
	label: 'Galveston Pier 21, TX',
	latitude: 29.31,
	longitude: -94.7933,
	station: '8771450',
	timeZone: 'America/Chicago'
};

const chartConfig = {
	height: { label: 'Tide level', color: 'var(--chart-1)' }
};
type ChartPoint = { time: number; height: number };

const formatTime = (value: string | number, timeZone: string) =>
	new Intl.DateTimeFormat('en-US', {
		hour: 'numeric',
		minute: '2-digit',
		timeZone
	}).format(typeof value === 'string' ? tideTimestamp(value) : value);

const formatDateTime = (value: string, timeZone: string) =>
	new Intl.DateTimeFormat('en-US', {
		month: 'short',
		day: 'numeric',
		hour: 'numeric',
		minute: '2-digit',
		timeZone
	}).format(tideTimestamp(value));

function TideTooltipContent({
	onHover,
	displayTimeZone,
	unit,
	...props
}: ComponentProps<typeof ChartTooltipContent> & {
	onHover: (point: ChartPoint | null) => void;
	displayTimeZone: string;
	unit: TideUnit;
}) {
	const payloadPoint = props.payload?.[0]?.payload as Partial<ChartPoint> | undefined;
	useEffect(() => {
		onHover(
			payloadPoint?.time !== undefined && payloadPoint.height !== undefined
				? { time: payloadPoint.time, height: payloadPoint.height }
				: null
		);
	}, [onHover, payloadPoint?.height, payloadPoint?.time]);
	const symbol = unit === 'meter' ? 'm' : 'ft';
	const convertedHeight = (value: number) => (value * (unit === 'meter' ? 0.3048 : 1)).toFixed(1);
	return (
		<ChartTooltipContent
			{...props}
			labelFormatter={() =>
				payloadPoint?.time === undefined
					? 'Tide level'
					: formatTime(payloadPoint.time, displayTimeZone)
			}
			formatter={(value) => `${convertedHeight(Number(value))} ${symbol}`}
		/>
	);
}

export function TideForecast({
	iconType,
	timeZone,
	type = 'summary',
	size = 'default',
	density = 'comfortable',
	className = '',
	unit = 'ft',
	location = defaultLocation,
	predictions = sampleTides,
	example,
	series,
	reading = null,
	at,
	sourceLabel = 'Sample tides'
}: TideForecastProps) {
	const [visitorTimeZone, setVisitorTimeZone] = useState('UTC');
	const [clock, setClock] = useState<number | null>(null);
	const [hovered, setHovered] = useState<{ time: number; height: number } | null>(null);
	useEffect(() => {
		setVisitorTimeZone(Intl.DateTimeFormat().resolvedOptions().timeZone);
		setClock(Date.now());
		const timer = window.setInterval(() => setClock(Date.now()), 60_000);
		return () => window.clearInterval(timer);
	}, []);

	const displayTimeZone = timeZone ?? visitorTimeZone;
	const isSample = example ?? predictions === sampleTides;
	const now = at ?? (isSample ? sampleTideTime : (clock ?? 0));
	const tide = useMemo(
		() => tideState(predictions, series ?? (isSample ? sampleTideSeries : []), reading, now),
		[predictions, series, isSample, reading, now]
	);
	const chartData = useMemo<ChartPoint[]>(() => {
		const curveData = tide.points.filter(
			(point: ChartPoint) =>
				point.time >= now - 12 * 60 * 60 * 1000 && point.time <= now + 18 * 60 * 60 * 1000
		);
		if (tide.predicted !== null && !curveData.some((point: ChartPoint) => point.time === now)) {
			return [...curveData, { time: now, height: tide.predicted }].sort(
				(a: ChartPoint, b: ChartPoint) => a.time - b.time
			);
		}
		return curveData;
	}, [now, tide.points, tide.predicted]);
	const domain = useMemo(() => {
		const values = chartData.map((point: ChartPoint) => point.height);
		if (tide.level !== null) values.push(tide.level);
		if (!values.length) return [0, 1] as [number, number];
		const low = Math.min(...values);
		const high = Math.max(...values);
		const padding = Math.max(0.15, (high - low) * 0.2);
		return [low - padding, high + padding] as [number, number];
	}, [chartData, tide.level]);
	const height = (value: number) => (value * (unit === 'meter' ? 0.3048 : 1)).toFixed(1);
	const symbol = unit === 'meter' ? 'm' : 'ft';
	const displayedLevel = hovered?.height ?? tide.level;
	const displayedTime = hovered?.time ?? (tide.observed ? tideTimestamp(tide.observed.time) : now);
	const indicatorTime = hovered?.time ?? now;
	const indicatorLevel = hovered?.height ?? tide.predicted;
	const timeParts = new Intl.DateTimeFormat('en-US', {
		hour: 'numeric',
		minute: '2-digit',
		timeZone: displayTimeZone
	}).formatToParts(displayedTime);
	const chartHeight = size === 'sm' ? 80 : size === 'lg' ? 144 : 112;
	const handleHover = useCallback((point: ChartPoint | null) => setHovered(point), []);
	if (
		!isSample &&
		(predictions.length > 0 || (series?.length ?? 0) > 0) &&
		at === undefined &&
		clock === null
	) {
		return (
			<Card
				style={{ containerType: 'inline-size' }}
				data-density={density}
				data-card-size={size}
				data-size={size === 'sm' ? 'sm' : 'default'}
				className={`min-w-0 overflow-hidden ${className}`}
			>
				<CardHeader>
					<CardTitle>Tides</CardTitle>
					<CardDescription>{location.label}</CardDescription>
				</CardHeader>
				<CardContent>
					<p role="status" className="py-8 text-center text-sm text-muted-foreground">
						Loading current tide time…
					</p>
				</CardContent>
			</Card>
		);
	}

	return (
		<Card
			style={{ containerType: 'inline-size' }}
			data-density={density}
			data-card-size={size}
			data-size={size === 'sm' ? 'sm' : 'default'}
			className={`min-w-0 overflow-hidden ${className}`}
		>
			<CardHeader>
				<CardTitle>Tides</CardTitle>
				<CardDescription>{location.label}</CardDescription>
			</CardHeader>
			<CardContent className={`${density === 'compact' ? 'grid gap-3' : 'grid gap-5'}`}>
				{tide.events.length || tide.points.length ? (
					<>
						<div className="flex flex-wrap items-end justify-between gap-3">
							<div>
								<p className="mb-1 text-xs text-muted-foreground">
									{hovered
										? 'Predicted water level'
										: isSample
											? 'Example water level'
											: tide.observed
												? 'Current water level'
												: tide.predicted !== null
													? 'Predicted water level'
													: 'High/low predictions only'}
								</p>
								<p
									style={{ fontSize: 'clamp(1.5rem, 12cqw, 2.5rem)' }}
									className={`${size === 'sm' ? 'text-3xl' : 'text-4xl'} font-medium tracking-tight tabular-nums`}
								>
									{displayedLevel === null ? (
										'—'
									) : (
										<NumberFlow
											value={Number(height(displayedLevel))}
											format={{ minimumFractionDigits: 1, maximumFractionDigits: 1 }}
										/>
									)}
									<span className="ml-1 text-sm text-muted-foreground">{symbol}</span>
								</p>
							</div>
							<div className="text-right text-xs text-muted-foreground">
								<p>
									{hovered
										? 'Selected time'
										: tide.next
											? tide.next.type === 'H'
												? 'Rising toward high tide'
												: 'Falling toward low tide'
											: 'Tide outlook'}
								</p>
								<p className="mt-1 tabular-nums" data-slot="tide-time">
									<span className="sr-only">{formatTime(displayedTime, displayTimeZone)}</span>
									<span aria-hidden="true">
										{timeParts.map((part, index) =>
											part.type === 'hour' || part.type === 'minute' ? (
												<NumberFlow
													key={`${part.type}-${index}`}
													value={Number(part.value)}
													format={{
														minimumIntegerDigits: part.type === 'minute' ? 2 : 1,
														useGrouping: false
													}}
												/>
											) : (
												part.value
											)
										)}
									</span>
								</p>
							</div>
						</div>
						{chartData.length > 1 ? (
							<>
								<ChartContainer
									config={chartConfig}
									className={`aspect-auto w-full ${size === 'sm' ? 'h-20' : size === 'lg' ? 'h-36' : 'h-28'}`}
									role="img"
									aria-label="Tide prediction curve with predicted water level marker"
								>
									<AreaChart
										data={chartData}
										height={chartHeight}
										margin={{ top: 8, right: 8, bottom: 4, left: 8 }}
										onMouseMove={(state) => {
											const index = Number(state.activeTooltipIndex);
											const point = Number.isInteger(index) ? chartData[index] : undefined;
											setHovered(point ?? null);
										}}
										onMouseLeave={() => setHovered(null)}
									>
										<CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 4" />
										<XAxis
											dataKey="time"
											type="number"
											domain={[chartData[0].time, chartData[chartData.length - 1].time]}
											hide
										/>
										<YAxis hide domain={domain} />
										<ChartTooltip
											content={
												<TideTooltipContent
													indicator="line"
													onHover={handleHover}
													displayTimeZone={displayTimeZone}
													unit={unit}
												/>
											}
										/>
										<Area
											type="monotone"
											dataKey="height"
											name="Tide level"
											stroke="var(--chart-1)"
											fill="var(--chart-1)"
											fillOpacity={0.12}
											strokeWidth={2}
											isAnimationActive={false}
										/>
										{indicatorLevel !== null &&
										indicatorTime >= chartData[0].time &&
										indicatorTime <= chartData[chartData.length - 1].time ? (
											<>
												<ReferenceLine
													x={indicatorTime}
													stroke="var(--muted-foreground)"
													strokeDasharray="3 4"
												/>
												<ReferenceDot
													x={indicatorTime}
													y={indicatorLevel}
													r={4.5}
													fill="var(--chart-1)"
													stroke="var(--card)"
													strokeWidth={2}
													data-slot="current-tide-marker"
												/>
											</>
										) : null}
									</AreaChart>
								</ChartContainer>
								<div className="-mt-2 flex justify-between text-[10px] text-muted-foreground">
									<span>{formatTime(chartData[0].time, displayTimeZone)}</span>
									<span>
										<Badge variant="outline" className="h-4 px-1 text-[9px]">
											MLLW
										</Badge>{' '}
										· {tide.points.length ? 'predicted curve' : 'extrema only'}
									</span>
									<span>{formatTime(chartData.at(-1)!.time, displayTimeZone)}</span>
								</div>
							</>
						) : null}
						<div className="grid grid-cols-2 gap-3 border-t pt-3">
							{[
								{ label: 'Previous', event: tide.previous },
								{ label: 'Next', event: tide.next }
							].map(({ label, event }) => (
								<div key={label}>
									<p className="text-xs text-muted-foreground">
										{label} {event ? (event.type === 'H' ? 'high tide' : 'low tide') : 'tide'}
									</p>
									<p className="mt-1 text-sm font-medium tabular-nums">
										{event ? formatTime(event.time, displayTimeZone) : 'Unavailable'}
									</p>
									{event ? (
										<p className="mt-1 text-xs text-muted-foreground">
											{height(Number(event.height))} {symbol}
										</p>
									) : null}
								</div>
							))}
						</div>
						{type !== 'simple' ? (
							<div className="divide-y border-t">
								{(tide.events as TidePrediction[])
									.filter((event: TidePrediction) => tideTimestamp(event.time) > now)
									.slice(0, type === 'detailed' ? 6 : density === 'compact' ? 2 : 4)
									.map((event: TidePrediction) => (
										<div
											key={`${event.time}-${event.type}`}
											className={`flex justify-between gap-2 text-xs ${density === 'compact' ? 'py-2' : 'py-3'}`}
										>
											<span className="flex items-center gap-1">
												{event.type === 'H' ? (
													<ForecastIcon
														name="arrowUp"
														iconSet={iconType}
														className="size-3"
														aria-hidden="true"
													/>
												) : (
													<ForecastIcon
														name="arrowDown"
														iconSet={iconType}
														className="size-3"
														aria-hidden="true"
													/>
												)}
												{event.type === 'H' ? 'High tide' : 'Low tide'}
											</span>
											<span className="ml-auto text-muted-foreground">
												{formatDateTime(event.time, displayTimeZone)}
											</span>
											<span className="tabular-nums">
												{height(Number(event.height))} {symbol}
											</span>
										</div>
									))}
							</div>
						) : null}
					</>
				) : (
					<p role="status" className="py-8 text-center text-sm text-muted-foreground">
						No tide predictions available.
					</p>
				)}
				{sourceLabel ? <p className="text-[10px] text-muted-foreground">{sourceLabel}</p> : null}
			</CardContent>
		</Card>
	);
}

export default TideForecast;

import { IconPlaceholder } from '@/components/icon-placeholder';
export type IconName = 'arrowUp' | 'arrowDown' | 'weather' | 'sun' | 'moon' | 'tide' | 'wind' | 'rain' | 'snow';
export type IconSet = 'lucide' | 'tabler' | 'phosphor' | 'hugeicons' | 'remixicon';
export type ForecastIconProps = { name: IconName; iconSet?: IconSet; className?: string };
export function ForecastIcon({ name, className = 'size-5' }: ForecastIconProps) {
 switch (name) {
 case 'arrowUp': return <IconPlaceholder lucide="ArrowUpIcon" tabler="IconArrowUp" phosphor="ArrowUpIcon" hugeicons="ArrowUp02Icon" remixicon="RiArrowUpLine" className={className} aria-hidden="true" />;
case 'arrowDown': return <IconPlaceholder lucide="ArrowDownIcon" tabler="IconArrowDown" phosphor="ArrowDownIcon" hugeicons="ArrowDown02Icon" remixicon="RiArrowDownLine" className={className} aria-hidden="true" />;
case 'weather': return <IconPlaceholder lucide="CloudSunIcon" tabler="IconCloud" phosphor="CloudSunIcon" hugeicons="SunCloud02Icon" remixicon="RiCloudy2Line" className={className} aria-hidden="true" />;
case 'sun': return <IconPlaceholder lucide="SunIcon" tabler="IconSun" phosphor="SunIcon" hugeicons="Sun03Icon" remixicon="RiSunLine" className={className} aria-hidden="true" />;
case 'moon': return <IconPlaceholder lucide="MoonIcon" tabler="IconMoon" phosphor="MoonIcon" hugeicons="Moon02Icon" remixicon="RiMoonLine" className={className} aria-hidden="true" />;
case 'tide': return <IconPlaceholder lucide="WavesIcon" tabler="IconWavesElectricity" phosphor="WavesIcon" hugeicons="WaterfallUp01Icon" remixicon="RiWaterFlashLine" className={className} aria-hidden="true" />;
case 'wind': return <IconPlaceholder lucide="WindIcon" tabler="IconWind" phosphor="WindIcon" hugeicons="WindPower02Icon" remixicon="RiWindyLine" className={className} aria-hidden="true" />;
case 'rain': return <IconPlaceholder lucide="CloudRainIcon" tabler="IconCloudRain" phosphor="CloudRainIcon" hugeicons="CloudRainIcon" remixicon="RiRainyLine" className={className} aria-hidden="true" />;
case 'snow': return <IconPlaceholder lucide="SnowflakeIcon" tabler="IconSnowflake" phosphor="SnowflakeIcon" hugeicons="SnowIcon" remixicon="RiSnowyLine" className={className} aria-hidden="true" />;
 }
}

export type CardSize = 'sm' | 'default' | 'lg';
export type CardDensity = 'compact' | 'comfortable';
export type ForecastType = 'summary' | 'detailed' | 'simple';
export type IconSet = 'hugeicons' | 'phosphor-svelte' | 'lucide' | 'tabler' | 'remix';
export type WeatherUnit = 'fahrenheit' | 'celsius';
export type TideUnit = 'ft' | 'meter';

export type LocationInput = {
	label?: string;
	latitude: number;
	longitude: number;
	station?: string;
	timeZone?: string;
};

export type WeatherPeriod = {
	name: string;
	startTime: string;
	endTime?: string;
	temperature: number;
	temperatureUnit: string;
	windSpeed: string;
	windDirection: string;
	shortForecast: string;
	detailedForecast: string;
	isDaytime: boolean;
};

export type TidePrediction = {
	time: string;
	height: string;
	type: 'H' | 'L';
};

export type MoonForecast = {
	date: string;
	phaseName: string;
	illumination: number;
	age: number;
	nextFullMoon: string;
	nextNewMoon: string;
};

/** Feet above MLLW. Prefer ISO 8601 timestamps with an explicit offset. */
export type TidePoint = { time: string; height: string };
export type TideReading = TidePoint;

/** Current observed conditions; daily extrema use temperatureUnit and the location's calendar day. */
export type CurrentWeather = WeatherPeriod & {
	observedAt: string;
	highToday?: number;
	lowToday?: number;
};

import type { LocationInput, TidePrediction } from './types.js';

type NoaaPrediction = {
	t: string;
	v: string;
	type: 'H' | 'L';
};

type NoaaResponse = {
	predictions: NoaaPrediction[];
};

export async function fetchTidePredictions(location: LocationInput, date = new Date()) {
	if (!location.station) {
		throw new Error('NOAA tide predictions require a CO-OPS station id.');
	}

	const begin = date.toISOString().slice(0, 10).replaceAll('-', '');
	const url = new URL('https://api.tidesandcurrents.noaa.gov/api/prod/datagetter');
	url.search = new URLSearchParams({
		product: 'predictions',
		application: 'wxcn',
		begin_date: begin,
		range: '48',
		datum: 'MLLW',
		station: location.station,
		time_zone: 'gmt',
		units: 'english',
		interval: 'hilo',
		format: 'json'
	}).toString();

	const response = await fetch(url);
	if (!response.ok) {
		throw new Error(`NOAA tide lookup failed with ${response.status}`);
	}

	const data = (await response.json()) as NoaaResponse;
	return data.predictions.map((prediction) => ({
		time: prediction.t.replace(' ', 'T') + 'Z',
		height: prediction.v,
		type: prediction.type
	})) satisfies TidePrediction[];
}

export const sampleTides: TidePrediction[] = [
	{ time: '2026-09-06T02:12:00-05:00', height: '1.8', type: 'H' },
	{ time: '2026-09-06T08:28:00-05:00', height: '0.4', type: 'L' },
	{ time: '2026-09-06T14:49:00-05:00', height: '1.5', type: 'H' },
	{ time: '2026-09-06T21:07:00-05:00', height: '0.3', type: 'L' }
];

export const sampleTideTime = Date.parse('2026-09-06T16:30:00Z');
// Illustrative six-minute samples, used only by the labeled coastal example.
export const sampleTideSeries = Array.from({ length: 241 }, (_, i) => {
	const time = Date.parse('2026-09-06T05:00:00Z') + i * 360000;
	return {
		time: new Date(time).toISOString(),
		height: (
			0.95 +
			0.65 *
				Math.cos(((time - Date.parse('2026-09-06T07:12:00Z')) / (12.6 * 3600000)) * 2 * Math.PI)
		).toFixed(3)
	};
});

import type { TidePrediction, TideReading, TidePoint } from './types.js';

// Offset-free legacy NOAA values are station wall times; all new API data uses UTC.
export function tideTimestamp(time: string) {
	return Date.parse(/[zZ]|[+-]\d\d:\d\d$/.test(time) ? time : time.replace(' ', 'T') + 'Z');
}
export function tideState(
	predictions: TidePrediction[],
	series: TidePoint[],
	reading: TideReading | null,
	now: number
) {
	const events = predictions
		.filter((p) => Number.isFinite(tideTimestamp(p.time)) && Number.isFinite(Number(p.height)))
		.toSorted((a, b) => tideTimestamp(a.time) - tideTimestamp(b.time));
	const previous = events.filter((p) => tideTimestamp(p.time) <= now).at(-1);
	const next = events.find((p) => tideTimestamp(p.time) > now);
	const points = series
		.map((p) => ({ time: tideTimestamp(p.time), height: Number(p.height) }))
		.filter((p) => Number.isFinite(p.time) && Number.isFinite(p.height))
		.toSorted((a, b) => a.time - b.time);
	const before = points.filter((p) => p.time <= now).at(-1),
		after = points.find((p) => p.time >= now);
	const predicted =
		before && after
			? before.height +
				(after.height - before.height) *
					(after.time === before.time ? 0 : (now - before.time) / (after.time - before.time))
			: null;
	const observed =
		reading &&
		reading.height.trim() &&
		Number.isFinite(Number(reading.height)) &&
		now - tideTimestamp(reading.time) >= 0 &&
		now - tideTimestamp(reading.time) <= 30 * 60000
			? reading
			: null;
	return {
		events,
		previous,
		next,
		points,
		predicted,
		observed,
		level: observed ? Number(observed.height) : predicted
	};
}
